package com.cinenest.notifications.internal;
import org.junit.jupiter.api.Test;import org.springframework.mock.env.MockEnvironment;import static org.assertj.core.api.Assertions.*;
class NotificationPolicyTest {
 @Test void productionOrMissingConfigurationFailsClosed(){var e=new MockEnvironment();var p=new NotificationPolicy(e);assertThatThrownBy(p::configured).isInstanceOf(NotificationFailure.class);e.withProperty("cinenest.notifications.enabled","true").withProperty("cinenest.notifications.channel","EMAIL").withProperty("cinenest.notifications.adapter","LOCAL_CAPTURE_SIMULATOR");assertThatThrownBy(p::configured).isInstanceOf(NotificationFailure.class);}
 @Test void everyExplicitLimitAndAccountAllowlistIsRequired(){var e=new MockEnvironment().withProperty("cinenest.notifications.enabled","true").withProperty("cinenest.notifications.channel","IN_APP_SYNTHETIC").withProperty("cinenest.notifications.adapter","LOCAL_CAPTURE_SIMULATOR").withProperty("cinenest.notifications.synthetic-accounts",java.util.UUID.randomUUID().toString());for(String k:java.util.List.of("expiry-seconds","retention-seconds","attempt-limit","retry-seconds","lease-seconds","rate-count","rate-seconds"))e.withProperty("cinenest.notifications."+k,"10");var p=new NotificationPolicy(e);p.configured();e.withProperty("cinenest.notifications.attempt-limit","0");assertThatThrownBy(p::configured).isInstanceOf(NotificationFailure.class);}
}
